reversing.decompiler_pattern:
unsigned int rotl32(unsigned int x, int n) {
  return (x << n) | (x >> (32 - n));
}

reversing.ida_example:
v3 = __ROL4__(v2, 7);
; 또는 최적화된 x86 어셈블리에서는
