reversing.decompiler_pattern:
unsigned int bswap32(unsigned int x) {
  return ((x & 0xFF) << 24) | ((x & 0xFF00) << 8) |
         ((x >> 8) & 0xFF00) | ((x >> 24) & 0xFF);
}
; 또는
result = __builtin_bswap32(v);

